}


#tt-body-page .area-slogun {
  display: none;
}

#tt-body-page .main {
  padding-top: 470px;
}

#tt-body-page .area-view img {
  display: inline-block;
  max-width: 100% !important;
  margin: 0;
  height: auto;
}

