  content:'';
  position: absolute;
  left: 50%;
  width: 100vw;
  height: 1px;
  margin-left: -50vw;
  border-bottom: 1px solid #efefef;}
.header .borderbottomline:after {
  border-bottom: none;} */
.header .title-logo {
  display: flex;
  flex-direction: column;
  justify-content: center;
  margin: 30px 0;
}

.header .link_logo {
  display: block;
  max-width: 220px;
  font-size: 18px;
  font-weight: 600;
  color: #333;
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  min-height: 22px;
}

.header .link_logo img {
  max-height: 18px;
}

.header .box-log {
  position: absolute;
  top: -1px;
  right: 0;
}

.header .button-menu {
  display: none;
  position: absolute;
  top: 21px;
  right: 80px;
  padding: 10px;
  border: none;
  background: none;
  cursor: pointer;
  opacity: 1;
}

.header .button-menu:hover {
  opacity: .7;
  transition: .2s ease-out;
}

.header .area-slogun {
  padding-top: 33px;
  padding-bottom: 36px;
}

.header .area-slogun strong {
  margin-bottom: 9px;
  font-size: 36px;
  font-family: Arial;

  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  max-height: 82px;
  overflow: hidden;
  white-space: normal;
  word-break: keep-all;
}

.header .area-slogun p {
  width: 500px;
  margin: 0;
  font-size: 13px;
  line-height: 19px;
  color: #999;
  word-break: keep-all;
}

.header .area-gnb .topnavnone {
  display: none;
}

.header .tt_category {
  margin: 0;
  padding: 0;
}

.header .tt_category ul {
  padding: 0;
  list-style: none;
}

.header .tt_category li {
  list-style: none;
  margin: 0;
  padding: 0;
}

.header .tt_category .link_tit {
  display: none;
}

.header .tt_category .category_list,
.header .topnavmenu>ul {
  font-size: 0;
  text-align: left;
  margin: 0;
  margin-bottom: -3px;
  padding: 0;
  list-style: none;
  white-space: nowrap;
  -webkit-overflow-scrolling: touch;
}

.header .tt_category .category_list li,
.header .topnavmenu>ul>li {
  display: inline-block;
  margin-right: 61px;
}

.header .topnavmenu>ul>li {
  /* padding-bottom: 32px; */
}

.header .tt_category .category_list li:last-child,
.header .topnavmenu>ul>li:last-child {
  margin-right: 0;
}

.header .tt_category .category_list .link_item,
.header .topnavmenu>ul>li>a {
  position: relative;
  display: block;
  font-size: 16px;
  font-weight: 500;
  color: #333 !important;
  text-decoration: none;
  white-space: nowrap;
  z-index: 2;
}

.header .tt_category .category_list .c_cnt {
