/* ==========================================================================
   Jaden.log — Dark Chrome / Paper Card
   티스토리 Odyssey 스킨 오버라이드  ·  v3 (실제 스킨 CSS 대조 후 재작성)

   ⚠️ 붙여넣기 전에 할 일
   기존 CSS 맨 아래에 있는 커스텀 블록 **두 개를 모두 지운다**:
     ① "Jaden.log — Dark Chrome / Paper Card 오버라이드"
     ② "Jaden.log — 오디세이(Odyssey) 스킨용 애플 스타일 커스텀 CSS v2"
   ②가 ① 뒤에 있으면서 !important 로 라이트 테마를 다시 씌우고 있었다.
   이 파일이 그 둘을 합친 결과물이다. 스킨 원본 CSS(`.cont-empty` 규칙까지)는 그대로 둔다.
   ========================================================================== */

@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

:root {
  /* 어두운 뼈대 */
  --jd-canvas:      #14161B;
  --jd-canvas-2:    #1C1F26;   /* 다크 카드 (목록·사이드바) */
  --jd-canvas-3:    #242832;   /* 다크 카드 hover */
  --jd-drawer:      #16191F;
  --jd-line:        rgba(255,255,255,.09);
  --jd-line-2:      rgba(255,255,255,.18);
  --jd-text:        #E9EBEF;
  --jd-text-2:      #9DA4AE;
  --jd-text-3:      #6F7681;

  /* 흰 종이 (글이 앉는 자리) */
  --jd-paper:       #FFFFFF;
  --jd-paper-line:  rgba(0,0,0,.08);
  --jd-ink:         #1D1D1F;
  --jd-ink-2:       #6E6E73;
  --jd-ink-3:       #86868B;
  --jd-surface:     #F5F5F7;

  --jd-accent:      #0071E3;   /* 채운 버튼 · 종이 위 링크 */
  --jd-accent-hi:   #0A80F2;
  --jd-accent-lit:  #5AA9FF;   /* 어두운 배경 위 링크 */

  --jd-r:           20px;
  --jd-r-sm:        14px;
  --jd-shadow:      0 1px 2px rgba(0,0,0,.30), 0 14px 34px -14px rgba(0,0,0,.50);
  --jd-font: "Pretendard Variable", Pretendard, -apple-system, BlinkMacSystemFont,
             "Apple SD Gothic Neo", "Noto Sans KR", sans-serif;
}

/* ==========================================================================
   1. 캔버스 · 타이포
   스킨이 body#tt-body-* 로 배경을 잡으므로 ID 특이성을 이겨야 한다.
   ========================================================================== */
html,
body[id] { background: var(--jd-canvas) !important; }

body {
  color: var(--jd-text);
  font-family: var(--jd-font) !important;
  letter-spacing: -.01em;
  -webkit-font-smoothing: antialiased;
}
body *:not(pre):not(code):not(pre *):not(code *):not([class^="xi-"]) {
  font-family: var(--jd-font) !important;
}
#wrap,
#container,
.main { background: var(--jd-canvas); }

::selection { background: rgba(0,113,227,.32); color: #fff; }

/* 다크 스크롤바 */
* { scrollbar-color: rgba(255,255,255,.18) transparent; }
::-webkit-scrollbar { width: 11px; height: 11px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,.16);
  border: 3px solid var(--jd-canvas);
  border-radius: 999px;
}
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,.28); }

/* 드로어 열릴 때 덮는 막 — 스킨 기본값이 흰색(rgba(255,255,255,.8))이라 반드시 뒤집는다 */
.bg-dimmed:before { background: rgba(0,0,0,.55) !important; }

/* ==========================================================================
   2. 헤더
   ========================================================================== */
header.header {
  background: var(--jd-canvas) !important;
  border-bottom: 1px solid var(--jd-line) !important;
  box-shadow: none !important;
}
.header .line-bottom { border-bottom-color: var(--jd-line) !important; }

.header .title-logo a.link_logo {
  color: #F2F4F7 !important;
  font-weight: 700 !important;
  letter-spacing: -.02em !important;
}

/* GNB — 스킨이 color:#333 !important 로 못박아 두었으므로 같은 선택자 + !important 필요 */
.header .tt_category .category_list .link_item,
.header .topnavmenu > ul > li > a {
  color: var(--jd-text-2) !important;
  font-weight: 500 !important;
  transition: color .15s ease;
}
.header .tt_category .category_list .link_item:hover,
.header .topnavmenu > ul > li > a:hover,
.header .tt_category .category_list .selected,
.header .topnavmenu > ul > li.selected > a { color: #FFFFFF !important; }

/* hover 밑줄 바 — 기본값 주황(#ef402f)을 액센트로 */
.header .tt_category .category_list > li:hover > a:after,
.header .topnavmenu > ul > li:hover > a:after { background: var(--jd-accent) !important; }

/* 2단 카테고리 드롭다운 패널 */
.header .tt_category .category_list .sub_category_list:before {
  border-top: 1px solid var(--jd-line) !important;
  background: var(--jd-canvas-2) !important;
}
.header .link_sub_item { color: var(--jd-text-2) !important; }
.header .link_sub_item:hover { color: #fff !important; }

/* 모바일에서 GNB 위/아래로 그어지는 회색 선 */
.header .area-gnb { border-top-color: var(--jd-line) !important; }
.header .area-gnb .topnavmenu { border-bottom-color: var(--jd-line) !important; }

/* --- 슬로건 히어로 --- */
header.header .area-slogun {
  text-align: center !important;
  padding: 60px 24px 52px !important;
  background: none !important;
  max-width: none !important;
}
header.header .area-slogun,
header.header .area-slogun strong,
header.header .area-slogun p {
  height: auto !important;
  max-height: none !important;
  overflow: visible !important;
  white-space: normal !important;
  -webkit-line-clamp: unset !important;
}
header.header .area-slogun strong,
header.header .area-slogun p {
  display: block !important;
  width: 100% !important;
  max-width: none !important;
  margin-left: auto !important;
  margin-right: auto !important;
  text-align: center !important;
  float: none !important;
}
header.header .area-slogun strong {
  font-size: clamp(28px, 4vw, 42px) !important;
  font-weight: 800 !important;
  letter-spacing: -.035em !important;
  line-height: 1.16 !important;
  color: #F7F9FC !important;
  word-break: keep-all;
}
header.header .area-slogun p {
  margin-top: 14px !important;
  font-size: 17px !important;
  color: var(--jd-text-2) !important;
  letter-spacing: -.01em !important;
}

/* --- 검색 인풋 (드로어 안 / 상단 겸용) --- */
.util .search { background-color: transparent !important; }
.util .search input,
.util .search .searchInput {
  background: rgba(255,255,255,.07) !important;
  border: 1px solid var(--jd-line) !important;
  border-radius: 999px !important;
  padding: 9px 16px !important;
  font-size: 13.5px !important;
  color: var(--jd-text) !important;
  transition: background .15s, border-color .15s;
}
.util .search input::placeholder,
.util .search .searchInput::placeholder { color: var(--jd-text-3) !important; }
.util .search input:focus,
.util .search .searchInput:focus {
  outline: none !important;
  background: rgba(255,255,255,.12) !important;
  border-color: var(--jd-line-2) !important;
}
.area-aside .box-search { border-bottom-color: var(--jd-line-2) !important; }
.area-aside .box-search .inp-search { background: transparent !important; color: var(--jd-text) !important; }

/* 햄버거 */
.header .button-menu svg path { fill: var(--jd-text) !important; stroke: var(--jd-text) !important; }

/* ==========================================================================
   3. 글 목록 — 다크 카드
   ========================================================================== */
h2.title-search,
.title-search {
  border: none !important;
  border-bottom: 1px solid var(--jd-line) !important;
  font-size: 15px !important;
  font-weight: 600 !important;
  color: var(--jd-text-2) !important;
  letter-spacing: -.01em;
}
.title-search b.archives { color: var(--jd-text) !important; font-weight: 700 !important; }
/* 기본값이 주황(#ef402f)인 카운트 */
.title-search span { color: var(--jd-accent-lit) !important; font-variant-numeric: tabular-nums; }

.area-cover .title-cover { color: var(--jd-text-2) !important; }
.box-cover-title .link-title { color: var(--jd-text-3) !important; }
.box-cover-title .link-title:after { border-color: var(--jd-text-3) !important; }
.area-cover-thumbnail .box-cover-title { border-bottom-color: var(--jd-line) !important; }

article.article-type-common {
  display: flex !important;
  flex-direction: row-reverse;
  align-items: center;
  gap: 28px;
  background: var(--jd-canvas-2) !important;
  border: 1px solid var(--jd-line) !important;
  border-radius: var(--jd-r) !important;
  box-shadow: none !important;
  padding: 24px 28px !important;
  margin: 0 0 16px !important;
  overflow: hidden;
  transition: background .18s ease, border-color .18s ease, transform .18s ease;
}
article.article-type-common:hover {
  background: var(--jd-canvas-3) !important;
  border-color: var(--jd-line-2) !important;
  transform: translateY(-2px);
}
article.article-type-common:hover .title { text-decoration: none !important; }

/* 썸네일 */
article.article-type-common .thumbnail {
  width: 176px !important;
  min-width: 176px;
  height: 118px !important;
  margin: 0 !important;
  border-radius: var(--jd-r-sm) !important;
  background-color: rgba(255,255,255,.05) !important;
  background-size: cover !important;
  background-position: 50% 50% !important;
  overflow: hidden;
}
article.article-type-common .thumbnail .img-thumbnail {
  width: 100%; height: 100%;
  object-fit: cover;
  border-radius: var(--jd-r-sm) !important;
}
article.article-type-common .thumbnail:not([has-thumbnail]) { display: none !important; }

/* 제목 · 요약 · 메타 */
article.article-type-common .article-content { flex: 1; min-width: 0; padding-top: 0 !important; }
article.article-type-common .title {
  color: #F1F3F6 !important;
  font-size: 21px !important;
  font-weight: 700 !important;
  letter-spacing: -.025em !important;
  line-height: 1.34 !important;
  max-height: none !important;
  margin-bottom: 8px !important;
}
article.article-type-common .summary {
  color: var(--jd-text-2) !important;
  font-size: 14.5px !important;
  line-height: 1.62 !important;
  margin: 0 0 13px !important;
}
article.article-type-common .box-meta { margin-top: 0 !important; }
article.article-type-common .link-category {
  color: var(--jd-accent-lit) !important;
  font-size: 12px !important;
  font-weight: 600 !important;
}
article.article-type-common .date,
article.article-type-common .reply {
  color: var(--jd-text-3) !important;
  font-size: 12.5px !important;
  font-variant-numeric: tabular-nums;
}
article.article-type-common .date:before,
article.article-type-common .reply:before { background: var(--jd-text-3) !important; }

/* 포스터형 / 텍스트형도 색만 맞춘다 */
.article-type-poster .title,
.article-type-text .title { color: #F1F3F6 !important; }
.article-type-poster .date,
.article-type-text .date { color: var(--jd-text-3) !important; }
.article-type-poster .thumbnail:before { background: rgba(255,255,255,.04) !important; }

/* 썸네일 없을 때 깔리는 밝은 플레이스홀더 */
.protected-img .thumbnail { background-color: rgba(255,255,255,.05) !important; }
.article-type-resize .protected-img .thumbnail { background-color: rgba(255,255,255,.05) !important; }

/* 태그 페이지 */
.area-tag .title-other { color: var(--jd-text) !important; }
.area-tag .box-tag a { color: var(--jd-text-2) !important; }
.area-tag .box-tag a:hover { color: var(--jd-accent-lit) !important; }

/* 검색 결과 없음 */
.box-no-search { color: var(--jd-text-3) !important; }
.box-no-search span:before { background: var(--jd-text-3) !important; }

/* 404 */
.notfoundpage .absent_post:before { color: var(--jd-text) !important; }
.notfoundpage .absent_post { color: var(--jd-text-3) !important; }

/* ==========================================================================
   4. 페이징
   ========================================================================== */
.area-paging .link_page { color: var(--jd-text-2) !important; }
.area-paging .link_page:hover { color: #fff !important; }   /* 기본 hover 가 주황 */
.area-paging .link_num span { color: var(--jd-text-2) !important; }
.area-paging .link_num:hover span {
  background: rgba(255,255,255,.10) !important;
  color: #fff !important;
}
.area-paging .selected,
.area-paging .link_num:hover .selected {
  background: var(--jd-accent) !important;
  color: #fff !important;
}

/* '더보기' — 기본은 전체폭 회색 테두리 박스. 가운데 알약으로 */
.paging-more {
  display: block !important;
  width: fit-content !important;
  margin: 4px auto 0 !important;
  padding: 0 28px !important;
  background: transparent !important;
  border: 1px solid var(--jd-line-2) !important;
  border-radius: 999px !important;
  color: var(--jd-text) !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  transition: background .15s, border-color .15s;
}
.paging-more:hover {
  background: var(--jd-accent) !important;
  border-color: transparent !important;
  color: #fff !important;
}
.paging-more-loading:before { border-color: var(--jd-line-2); border-top-color: var(--jd-accent-lit); }

/* ==========================================================================
   5. 글 헤더 (히어로)
      원본은 position:absolute + height:400px 고정이고, .box-meta 가 bottom:56px 로
      바닥에 붙는다. 그래서 제목 위로 200px 넘게 비어 있었고, .main 이 padding-top:470px
      으로 그 높이를 받쳐준다. 높이를 숫자로 줄이면 제목이 두 줄일 때 위로 넘친다.
      → 대표이미지 없는 글은 아예 '흐름 안'으로 되돌려 내용만큼만 차지하게 한다.
   ========================================================================== */
#tt-body-page .article-header.article-header-noimg {
  position: relative !important;
  top: auto; left: auto; right: auto;
  width: 100% !important;
  height: auto !important;
  margin: 0 !important;
  padding: 64px 0 44px !important;
  background: none !important;
}
#tt-body-page .article-header.article-header-noimg:before { display: none !important; }
#tt-body-page .article-header.article-header-noimg .inner-header {
  max-width: 780px;
  margin: 0 auto;
}
#tt-body-page .article-header.article-header-noimg .box-meta {
  position: static !important;
  bottom: auto !important;
  width: 100%;
  max-width: 780px;
}
/* 위 헤더가 흐름 안으로 들어왔으니 받침 패딩은 없어야 한다.
   대표이미지가 있는 글은 원본 470px 그대로 유지된다. */
body#tt-body-page:has(.article-header-noimg) .main { padding-top: 0 !important; }

.article-header .box-meta .category {
  color: var(--jd-accent-lit) !important;
  font-weight: 600 !important;
}
.article-header .title-article {
  color: #F7F9FC !important;
  font-weight: 800 !important;
  letter-spacing: -.032em !important;
  line-height: 1.22 !important;
  margin-bottom: 22px !important;
}
.article-header .box-info { opacity: 1 !important; }
.article-header .box-info,
.article-header .box-info .writer,
.article-header .box-info .date {
  color: var(--jd-text-3) !important;
  font-size: 13px !important;
  font-variant-numeric: tabular-nums;
}
.article-header .box-info .date:before { background: var(--jd-text-3) !important; }

/* ==========================================================================
   6. 본문 — 흰 종이 카드
   ========================================================================== */
#article-view.article-view {
  background: var(--jd-paper) !important;
  border-radius: var(--jd-r) !important;
  box-shadow: var(--jd-shadow);
  /* 좌우 60px = 본문 780px. 위 히어로의 .inner-header(780px)와 왼쪽 선이 정확히 맞는다 */
  padding: 40px 60px 6px !important;
  margin-bottom: 0 !important;
  color: var(--jd-ink);
  overflow: hidden;
}

/* 안 채워진 광고 슬롯 접기 — 죽은 공백의 가장 큰 원인.
   글 페이지: 본문 끝 ~ 공감 버튼 사이 280px + 여백 100px
   목록 페이지: 푸터 바로 앞 .revenue_unit_wrap.position_list 280px + 여백 60px
   광고가 실제로 뜨면 안에 iframe 이 생기므로 이 규칙은 적용되지 않는다.
   ※ 광고 자리를 항상 비워두고 싶으면 아래 두 블록만 지운다. */
.revenue_unit_wrap:empty,
.revenue_unit_wrap:not(:has(iframe)):not(:has(img)) {
  display: none !important;
  margin: 0 !important;
}
ins.adsbygoogle[data-ad-status="unfilled"],
ins.adsbygoogle:not(:has(iframe)) { display: none !important; }

/* 공감/공유 줄 — 원본 43px/36px */
.container_postbtn { padding: 22px 0 26px 0 !important; }

/* 카드 안의 '카테고리의 다른 글' 표 — 아래 '…의 다른글' 카드와 내용이 겹쳐 숨긴다 */
.another_category { display: none !important; margin: 0 !important; }

/* 본문 기본 요소 (글은 인라인 스타일이라 대부분 그대로지만, 빠진 것 대비) */
.article-view p { color: var(--jd-ink); }
.article-view h1, .article-view h2, .article-view h3, .article-view h4 {
  color: var(--jd-ink) !important;
  font-weight: 700 !important;
  letter-spacing: -.025em !important;
  line-height: 1.3 !important;
}
.article-view blockquote {
  border-left: 3px solid var(--jd-accent) !important;
  background: var(--jd-surface) !important;
  border-radius: 0 12px 12px 0;
  padding: 16px 22px !important;
  color: var(--jd-ink-2) !important;
}
.article-view pre {
  background: var(--jd-ink) !important;
  color: #F5F5F7 !important;
  border: none !important;
  border-radius: 12px !important;
}
#article-view pre code.hljs { border: none !important; border-radius: 12px !important; }
.article-view img { border-radius: var(--jd-r-sm) !important; }
#article-view a { color: var(--jd-accent); }

/* ==========================================================================
   7. 글 아래 블록 — '카드가 잘려 보이던' 자리
      이전글/현재글 · 관련글 · 댓글을 본문 카드와 같은 폭·같은 모서리의 카드로 세운다.
   ========================================================================== */
.article-footer { padding: 0; }

.article-footer > .article-page,
.article-footer > .article-related,
.article-footer > .article-reply,
.article-footer > .article-tag {
  background: var(--jd-paper);
  border: none !important;
  border-radius: var(--jd-r);
  box-shadow: var(--jd-shadow);
  padding: 28px 34px !important;
  margin: 20px 0 0 !important;
  color: var(--jd-ink);
  overflow: hidden;
}
.article-footer > .article-page { margin-top: 24px !important; }

.article-footer .title-footer {
  color: var(--jd-ink) !important;
  margin: 0 0 16px !important;
  padding: 0 0 13px;
  border-bottom: 1px solid var(--jd-paper-line);
  font-size: 14px !important;
  font-weight: 700 !important;
  letter-spacing: -.01em;
}

/* --- 이전글 / 현재글 / 다음글 --- */
.article-page ul { margin: 0 !important; padding: 0; }
.article-page ul li {
  display: flex;
  align-items: baseline;
  gap: 14px;
  margin: 0 !important;
  padding: 8px 0;
  font-size: 14.5px !important;
  color: var(--jd-ink) !important;
}
/* 다음글이 없을 때 생기는 빈 li */
.article-page ul li:not(:has(strong)) { display: none !important; }
/* 원본이 '현재글' 뒤에 넣는 ':' — flex 정렬과 어긋나므로 뺀다 */
.article-page ul li:nth-child(2):after { display: none !important; }
.article-page ul li span {
  flex: 0 0 50px;
  padding-right: 0 !important;
  color: var(--jd-ink-3) !important;
  font-size: 12.5px !important;
  font-weight: 600;
}
.article-page ul li a { color: var(--jd-ink) !important; text-decoration: none !important; }
.article-page ul li strong { font-weight: 600 !important; color: var(--jd-ink); }
.article-page ul li a:hover strong { color: var(--jd-accent) !important; text-decoration: none; }

/* --- 관련글 --- */
.article-related .list-related {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  margin: 0 !important;
  overflow: visible;
}
.article-related .item-related { width: calc(33.333% - 12px) !important; }
.article-related .item-related:last-child { display: block !important; }
.article-related .link-related { margin: 0 !important; }
.article-related .thumnail {
  border-radius: 12px !important;
  background-color: var(--jd-surface) !important;
}
.article-related .link-related strong { color: var(--jd-ink) !important; font-weight: 600 !important; }
.article-related .link-related:hover strong { color: var(--jd-accent) !important; }
.article-related .date { color: var(--jd-ink-3) !important; }

/* --- 태그 --- */
.article-tag { border-bottom: none !important; margin-bottom: 0 !important; padding-bottom: 0 !important; }
.article-tag .box-tag a {
  background: var(--jd-surface) !important;
  border: none !important;
  border-radius: 999px !important;
  color: var(--jd-ink-2) !important;
  padding: 6px 14px !important;
  font-size: 12.5px !important;
}
.article-tag .box-tag a:hover { background: rgba(0,113,227,.10) !important; color: var(--jd-accent) !important; }
/* 원본이 태그 사이를 흰 사각형으로 덮는 꼼수 — 종이 위라 흰색 그대로 둔다 */
.article-tag .box-tag a:after { background: var(--jd-paper) !important; }

/* --- 댓글 (티스토리가 밝은 배경 전제로 위젯을 끼워 넣으므로 종이 카드 유지) --- */
.article-footer > .article-reply { padding: 22px 28px 26px !important; margin-bottom: 0 !important; }
.article-reply .area-reply { background: transparent !important; margin-bottom: 0 !important; padding: 0 !important; box-shadow: none !important; }
.article-reply .box-total { border-bottom-color: var(--jd-paper-line) !important; }
.article-reply .box-total span { color: var(--jd-accent) !important; }
.area-reply textarea,
.area-reply input[type="text"],
.area-reply input[type="password"] {
  background: var(--jd-surface) !important;
  border: 1px solid transparent !important;
  border-radius: 12px !important;
  color: var(--jd-ink) !important;
}
.area-reply textarea:focus,
.area-reply input[type="text"]:focus,
.area-reply input[type="password"]:focus {
  outline: none !important;
  background: #fff !important;
  border-color: var(--jd-accent) !important;
}
.area-reply .btn_register,
.area-reply button[type="submit"] {
  background: var(--jd-accent) !important;
  border: none !important;
  border-radius: 999px !important;
  color: #fff !important;
}
.area-reply .btn_register:hover,
.area-reply button[type="submit"]:hover { background: var(--jd-accent-hi) !important; }

/* 본문 아래에 하나 더 붙어 빈 공백만 만들던 중복 댓글 블록 */
.area-view > .article-reply:not(:has(.tt-comment-cont)) { display: none !important; }
.article-reply .area-reply:not(:has(*)) { display: none !important; }

/* --------------------------------------------------------------------------
   7-b. 티스토리 댓글 위젯 (tt- 클래스)
        tistory.css 가 스킨 CSS보다 뒤에 로드되므로 대부분 !important 가 필요하다.
        아이콘은 SVG 스프라이트(tt_img_area_reply_*.svg)이므로 background 는 건드리지 않는다.
   -------------------------------------------------------------------------- */

/* --- 구독 카드: 225px 회색 덩어리 → 한 줄 높이의 조용한 행 --- */
.tt_box_namecard {
  position: relative !important;
  height: auto !important;
  min-height: 0 !important;
  align-items: center !important;
  background: transparent !important;
  border: 1px solid var(--jd-paper-line) !important;
  border-radius: var(--jd-r-sm) !important;
  margin: 0 0 22px !important;
  padding: 13px 18px !important;
}
/* DOM 순서가 [글 정보][썸네일] 이라 썸네일을 앞으로 당긴다 */
.tt_box_namecard .tt_wrap_thumb {
  order: -1;
  width: 40px !important;
  height: 40px !important;
  margin: 0 !important;
  border-radius: 50% !important;
  overflow: hidden;
}
.tt_box_namecard .tt_thumb_g {
  width: 40px !important;
  height: 40px !important;
  background-size: cover !important;
}
.tt_box_namecard .tt_cont {
  height: auto !important;
  padding: 0 128px 0 14px !important;
}
.tt_box_namecard .tt_tit_cont {
  font-size: 14.5px !important;
  font-weight: 600 !important;
  line-height: 1.35 !important;
  color: var(--jd-ink) !important;
}
.tt_box_namecard .tt_desc {
  padding: 2px 0 0 !important;
  font-size: 13px !important;
  line-height: 1.45 !important;
  color: var(--jd-ink-3) !important;
}
/* 구독 버튼을 카드 오른쪽에 세로 중앙으로 */
.tt_box_namecard .tt_btn_subscribe {
  position: absolute !important;
  top: 50%;
  right: 18px;
  transform: translateY(-50%);
  height: 32px !important;
  margin: 0 !important;
  border: 1px solid rgba(0,0,0,.16) !important;
  border-radius: 999px !important;
}
.tt_box_namecard .tt_btn_subscribe:hover {
  border-color: var(--jd-accent) !important;
  color: var(--jd-accent) !important;
}

/* --- '댓글 N' — 위 카드들의 제목 규칙과 같은 모양으로 --- */
.tt-box-total {
  margin: 0 0 4px !important;
  padding: 0 0 14px !important;
  border-bottom: 1px solid var(--jd-paper-line) !important;
}
.tt-box-total .tt_txt_g {
  font-size: 14px !important;
  font-weight: 700 !important;
  letter-spacing: -.01em;
  color: var(--jd-ink) !important;
}
.tt-box-total .tt_num_g {
  padding-left: 6px !important;
  font-size: 14px !important;
  font-weight: 700 !important;
  color: var(--jd-accent) !important;
  font-variant-numeric: tabular-nums;
}

/* --- 댓글 목록 --- */
.tt-area-reply { margin: 0 0 26px !important; }
.tt-list-reply { border-bottom: none !important; }
.tt-item-reply {
  padding: 18px 0 !important;
  border-bottom: 1px solid var(--jd-paper-line);
}
.tt-item-reply:last-child { border-bottom: none; padding-bottom: 6px !important; }

.tt-item-reply .tt-box-thumb { margin: 0 14px 0 0 !important; }
.tt-item-reply .tt-thumbnail {
  width: 40px !important;
  height: 40px !important;
  border-radius: 50% !important;
  background-size: cover !important;
}
.tt-box-meta { margin: 0 !important; align-items: center !important; }
.tt-link-user {
  font-size: 14.5px !important;
  font-weight: 600 !important;
  color: var(--jd-ink) !important;
}
.tt-wrap-desc { margin-top: 3px !important; }
.tt-wrap-desc .tt_desc {
  font-size: 15px !important;
  line-height: 1.62 !important;
  color: var(--jd-ink) !important;
  word-break: keep-all;
}
/* 비밀 댓글은 안내문이므로 흐리게 */
.tt_item_secret .tt-wrap-desc .tt_desc { color: var(--jd-ink-3) !important; }

.tt-wrap-info { height: auto !important; margin-top: 8px !important; }
.tt-wrap-info .tt_date,
.tt-item-reply .tt_date {
  padding: 0 !important;
  height: auto !important;
  font-size: 12.5px !important;
  color: var(--jd-ink-3) !important;
  font-variant-numeric: tabular-nums;
}

/* ⋯ 메뉴 · 비밀글 비밀번호 팝오버 */
.tt-list-modify,
.tt_box_pwd {
  border: 1px solid var(--jd-paper-line) !important;
  border-radius: 12px !important;
  box-shadow: 0 8px 24px rgba(0,0,0,.14) !important;
}
.tt-list-modify a,
.tt-list-modify button { color: var(--jd-ink-2) !important; }

/* --- 댓글 입력 --- */
.tt-area-write { padding-top: 2px; }
.tt-area-write .tt-box-thumb { margin: 0 14px 0 0 !important; }
.tt-area-write .tt-thumbnail {
  width: 40px !important;
  height: 40px !important;
  border-radius: 50% !important;
  background-size: cover !important;
}

.tt-box-account { gap: 8px; margin: 0 0 8px !important; }
.tt-box-account input {
  flex: 1 1 0;
  width: auto !important;
  background: var(--jd-surface) !important;
  border: 1px solid transparent !important;
  border-radius: 12px !important;
  padding: 11px 14px !important;
  font-size: 14px !important;
  color: var(--jd-ink) !important;
  transition: background .15s, border-color .15s;
}

/* textarea 를 감싸는 회색 2px-radius 상자가 둥근 입력칸과 이중으로 겹쳐 보였다.
   → 감싸는 쪽을 입력칸으로 만들고 안쪽 textarea 는 투명하게 눕힌다. */
.tt-box-textarea { margin: 0 0 12px !important; }
.tt-box-textarea .tt-inner-g {
  height: auto !important;            /* 110px 고정이라 입력칸 아래 40px 이 죽어 있었다 */
  overflow: hidden !important;        /* 스크롤바가 떠서 15px 를 먹고 입력칸이 오른쪽으로 비어 보였다 */
  background: var(--jd-surface) !important;
  border: 1px solid transparent !important;
  border-radius: 12px !important;
  padding: 12px 14px !important;
  transition: background .15s, border-color .15s;
}
.tt-box-textarea .tt-inner-g:focus-within {
  background: #FFFFFF !important;
  border-color: var(--jd-accent) !important;
}
.tt-box-textarea textarea,
.tt-box-textarea #comment {
  display: block !important;
  box-sizing: border-box !important;
  width: 100% !important;
  max-width: 100% !important;
  height: 92px !important;
  min-height: 92px;
  margin: 0 !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  font-size: 14.5px !important;
  line-height: 1.6 !important;
  color: var(--jd-ink) !important;
  resize: vertical;
}
.tt-box-account input:focus {
  outline: none !important;
  background: #FFFFFF !important;
  border-color: var(--jd-accent) !important;
}
.tt-box-account input::placeholder,
.tt-box-textarea textarea::placeholder { color: var(--jd-ink-3) !important; }

/* 비밀글 체크박스 — 라벨 텍스트가 font-size:0 으로 숨어 있었고
   체크박스에 margin-left:241px 이 하드코딩돼 카드 폭이 바뀌면 어긋났다 */
.tt-box-write { gap: 12px; }
.tt-xe-label { margin: 0 auto 0 0 !important; }
.tt-xe-label .tt-xe-input-helper { margin: 0 8px 0 0 !important; }
.tt-xe-label .tt-xe-label-text {
  width: auto !important;
  height: auto !important;
  font-size: 13px !important;
  line-height: 20px !important;
  color: var(--jd-ink-2) !important;
}

.tt-btn_register {
  height: 34px !important;
  padding: 0 20px !important;
  background: var(--jd-accent) !important;
  border: none !important;
  border-radius: 999px !important;
  color: #FFFFFF !important;
  font-size: 13.5px !important;
  font-weight: 500 !important;
  transition: background .15s;
}
.tt-btn_register:hover { background: var(--jd-accent-hi) !important; }

@media screen and (max-width: 768px) {
  .tt_box_namecard { padding: 12px 14px !important; }
  .tt_box_namecard .tt_cont { padding: 0 0 0 12px !important; }
  .tt_box_namecard .tt_btn_subscribe { position: static !important; transform: none; margin: 10px 0 0 !important; }
  .tt_box_namecard { flex-wrap: wrap !important; }
  .tt-box-account { flex-direction: column; }
  .tt-item-reply .tt-box-thumb,
  .tt-area-write .tt-box-thumb { margin-right: 10px !important; }
}

/* 보호글 입력 폼 */
.area-protected .text-protected { color: var(--jd-text) !important; }
.area-protected .text-protected span { color: var(--jd-text-2) !important; }
.area-protected input {
  background: rgba(255,255,255,.07) !important;
  border: 1px solid var(--jd-line) !important;
  border-radius: 10px !important;
  color: var(--jd-text) !important;
}
.area-protected button { background: rgba(255,255,255,.10) !important; color: var(--jd-text-2) !important; border-radius: 10px !important; }
.area-protected input.active + button { background: var(--jd-accent) !important; color: #fff !important; }

/* 마지막 카드와 푸터 사이 (원본 #footer margin-top:120px 를 흡수) */
.area-main { padding-bottom: 80px; }
#footer { margin-top: 0 !important; }

/* ==========================================================================
   8. 사이드바 (드로어)
   ========================================================================== */
.area-aside {
  background: var(--jd-drawer) !important;
  border-left: 1px solid var(--jd-line) !important;
  color: var(--jd-text);
}
.area-aside .box-profile,
.area-aside .box-category,
.area-aside .box-recent,
.area-aside .box-reply,
.area-aside .box-notice,
.area-aside .box-tag,
.area-aside .box-archive,
.area-aside .box-calendar,
.area-aside .box-visit,
.area-aside .box-plugins {
  background: var(--jd-canvas-2) !important;
  border: 1px solid var(--jd-line) !important;
  border-radius: var(--jd-r-sm) !important;
  padding: 18px 20px !important;
  margin-bottom: 14px !important;
  overflow: hidden;
}
.area-aside .box-profile { text-align: center; }
.area-aside .box-profile .img-profile {
  width: 96px !important; height: 96px !important;
  margin: 6px 0 12px !important;
  border: 1px solid var(--jd-line);
}
.area-aside .box-profile .tit-g { color: #F1F3F6 !important; padding: 0 !important; }
.area-aside .box-profile .text-profile { color: var(--jd-text-2) !important; margin-bottom: 18px !important; }
.area-aside .box-profile .group-btn { padding: 0 0 4px !important; }
.area-aside .box-profile .box-sns { margin: 20px 0 4px !important; }
.area-aside .box-profile .link-sns { border-color: var(--jd-line) !important; }
.area-aside .box-profile .link-sns svg path { fill: var(--jd-text-2) !important; }

.area-aside .title-sidebar {
  color: var(--jd-text-3) !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  letter-spacing: .08em !important;
  text-transform: uppercase;
  margin-bottom: 12px !important;
}
.area-aside .link-sidebar,
.area-aside .link-sidebar span { color: var(--jd-text-2) !important; }
.area-aside .link-sidebar:hover { color: #fff !important; }

.area-aside .box-category .tt_category .link_tit,
.area-aside .box-category .tt_category .category_list .link_item { color: var(--jd-text-2) !important; }
.area-aside .box-category .tt_category .link_tit:hover,
.area-aside .box-category .tt_category .category_list .link_item:hover { color: #FFFFFF !important; }
.area-aside .box-category .tt_category .category_list .link_item.selected,
.area-aside .box-category .tt_category .category_list .link_sub_item.selected { color: #FFFFFF !important; }
.area-aside .box-category .tt_category .category_list .link_sub_item { color: var(--jd-text-3) !important; }
.area-aside .box-category .tt_category .category_list .link_sub_item:before { background: var(--jd-text-3) !important; }
.area-aside .box-category .tt_category .category_list .link_sub_item:hover { color: #fff !important; }

.area-aside .box-tag a { color: var(--jd-text-2) !important; }
.area-aside .box-tag a:hover { color: var(--jd-accent-lit) !important; }
/* 원본이 태그 끝을 흰 사각형으로 덮는 꼼수 — 다크에서 흰 점으로 보인다 */
.area-aside .box-tag a:last-child:after { background: var(--jd-canvas-2) !important; }

.area-aside .box-recent .tab-recent li a,
.area-aside .box-plugins .tab-sns li a { color: var(--jd-text-3) !important; }
.area-aside .box-recent .tab-recent li.on a,
.area-aside .box-plugins .tab-sns li.on a { color: #FFFFFF !important; }
.area-aside .box-recent .list-recent .box-recent { color: var(--jd-text-2) !important; }
.area-aside .box-recent .list-recent .box-recent strong { color: #E4E7EC !important; }
.area-aside .box-recent .list-recent .box-recent span { color: var(--jd-text-3) !important; }
.area-aside .box-recent .list-recent .thumbnail {
  border-radius: 10px !important;
  background-color: rgba(255,255,255,.05) !important;
}

.box-reply .link-sidebar strong { color: #E4E7EC !important; }
.box-reply .list-sidebar p { color: var(--jd-text-3) !important; }

/* 캘린더 */
.area-aside .box-calendar .inner-calendar { border: none !important; padding: 0 !important; }
.area-aside .box-calendar .inner-calendar table th,
.area-aside .box-calendar .inner-calendar table td { color: var(--jd-text-3) !important; }
.area-aside .box-calendar .inner-calendar .cal_month a { color: #E4E7EC !important; }
.area-aside .box-calendar .inner-calendar table td a { color: var(--jd-accent-lit) !important; font-weight: 600; }
.box-calendar .cal_click { color: #FFFFFF !important; }

.area-aside .box-visit .text-total { color: #F1F3F6 !important; }
.area-aside .box-visit .item-visit { color: var(--jd-text-3) !important; }

/* 버튼 — 원본 hover 가 주황(#f54) */
.area-aside .box-profile .btn_subscription,
.btn-g {
  background: rgba(255,255,255,.06) !important;
  border: 1px solid var(--jd-line) !important;
  border-radius: 999px !important;
  color: var(--jd-text) !important;
  font-weight: 500 !important;
}
.area-aside .box-profile .btn_subscription:hover,
.btn-g:hover {
  background: rgba(255,255,255,.12) !important;
  border-color: var(--jd-line-2) !important;
  color: #fff !important;
}
.area-aside .box-profile .btn_subscription:not(.following),
.btn-primary {
  background: var(--jd-accent) !important;
  border-color: transparent !important;
  color: #fff !important;
}
.area-aside .box-profile .btn_subscription:not(.following):hover,
.btn-primary:hover { background: var(--jd-accent-hi) !important; border-color: transparent !important; }

.box-log a { color: var(--jd-text-3) !important; }
.box-log .link-log:before { background: var(--jd-line-2) !important; }

.cont-empty .tit-g { color: var(--jd-text) !important; }
.cont-empty .desc-g { color: var(--jd-text-3) !important; }

/* ==========================================================================
   9. 푸터
   ========================================================================== */
footer#footer {
  background: var(--jd-canvas) !important;
  border-top: 1px solid var(--jd-line) !important;
}
#footer .link-footer { color: var(--jd-text-2) !important; font-size: 12.5px !important; }
#footer .link-footer:hover { color: #fff !important; }
#footer .link-footer:before { background: var(--jd-text-3) !important; }
#footer .text-info,
#footer address { color: var(--jd-text-3) !important; font-size: 12px !important; }
#footer .box-site button {
  background: rgba(255,255,255,.06) !important;
  border: 1px solid var(--jd-line) !important;
  border-radius: 999px !important;
  color: var(--jd-text-2) !important;
  font-size: 12.5px !important;
}
#footer .box-site ul {
  background: var(--jd-canvas-2) !important;
  border: 1px solid var(--jd-line) !important;
  border-radius: 12px !important;
}
#footer .box-site ul li a { background: transparent !important; color: var(--jd-text-2) !important; }
#footer .box-site ul li a:hover { color: #fff !important; }

/* ==========================================================================
   10. 반응형 — 스킨 브레이크포인트(1060 / 768)를 그대로 따른다
   ========================================================================== */
@media screen and (max-width: 1060px) {
  #tt-body-page .article-header.article-header-noimg { padding: 40px 0 30px !important; }
  header.header .area-slogun { padding: 36px 0 32px !important; }

  article.article-type-common { padding: 18px 20px !important; gap: 18px; }
  article.article-type-common .thumbnail {
    width: 92px !important; min-width: 92px; height: 92px !important;
  }
  article.article-type-common .title { font-size: 17px !important; margin-bottom: 6px !important; }
  article.article-type-common .summary { font-size: 13px !important; margin-bottom: 10px !important; }

  #article-view.article-view { padding: 26px 20px 4px !important; }
  .article-footer > .article-page,
  .article-footer > .article-related,
  .article-footer > .article-reply,
  .article-footer > .article-tag { padding: 22px 20px !important; margin-top: 14px !important; }
  .article-footer > .article-page { margin-top: 16px !important; }

  .article-related .item-related { width: calc(50% - 9px) !important; min-width: 0 !important; }

  .area-aside .box-profile .img-profile { width: 84px !important; height: 84px !important; }
  .area-main { padding-bottom: 40px; }
}

@media screen and (max-width: 768px) {
  :root { --jd-r: 16px; }
  #tt-body-page .article-header.article-header-noimg { padding: 28px 0 24px !important; }
  .article-header .title-article { font-size: 26px !important; margin-bottom: 16px !important; }
  .article-page ul li { gap: 10px; font-size: 14px !important; }
  .article-page ul li span { flex-basis: 44px; }
  .article-related .item-related { width: 100% !important; }
}

/* ===================================================================
   v5 (2026-09-07) — 카테고리 개편 대응
   ① 홈 주제 카드 (.jd-topics) — body#tt-body-index 에서만 표시
   ② 글 하단 '…의 다른글' 제목에 카테고리 전체 보기 링크
   ③ 관련글 빈 썸네일 숨김
   =================================================================== */

/* --- ① 홈 주제 카드 --- */
.jd-topics { display: none; }
body#tt-body-index .jd-topics { display: block; margin: 0 0 44px; }
.jd-topics-head {
  display: flex; align-items: baseline; justify-content: space-between;
  margin: 0 0 14px; padding: 0 0 12px; border-bottom: 1px solid var(--jd-line);
}
.jd-topics-title { margin: 0; font-size: 14px; font-weight: 700; color: var(--jd-text); letter-spacing: .01em; }
.jd-topics-all { font-size: 12.5px; font-weight: 600; color: var(--jd-text-3) !important; text-decoration: none !important; }
.jd-topics-all:hover { color: var(--jd-accent-lit) !important; }
.jd-topics-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.jd-topic {
  display: flex; flex-direction: column; gap: 10px; min-width: 0;
  padding: 22px 22px 18px;
  background: var(--jd-canvas-2); border: 1px solid var(--jd-line); border-radius: var(--jd-r);
  transition: background .15s, border-color .15s;
}
.jd-topic:hover { background: var(--jd-canvas-3); border-color: var(--jd-line-2); }
.jd-topic-name {
  display: inline-block; font-size: 20px; font-weight: 800; letter-spacing: -.02em; line-height: 1.2;
  color: var(--jd-text) !important; text-decoration: none !important;
}
.jd-topic-name:hover { color: var(--jd-accent-lit) !important; }
.jd-topic-desc { flex: 1; margin: 0; font-size: 13.5px; line-height: 1.6; color: var(--jd-text-2); word-break: keep-all; }
.jd-topic-subs { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
.jd-topic-sub {
  display: inline-flex; align-items: baseline; gap: 5px;
  padding: 5px 11px; border-radius: 999px;
  font-size: 12.5px; font-weight: 600; line-height: 1.3;
  color: var(--jd-text) !important; text-decoration: none !important;
  background: rgba(255,255,255,.05); border: 1px solid var(--jd-line);
}
.jd-topic-sub:hover { border-color: var(--jd-accent-lit); color: var(--jd-accent-lit) !important; }
.jd-topic-sub em { font-style: normal; font-weight: 500; color: var(--jd-text-3); }
@media (max-width: 760px) {
  .jd-topics-grid { grid-template-columns: 1fr; }
  .jd-topic { padding: 18px 18px 16px; border-radius: 16px; }
}

/* --- ② '…의 다른글' 제목 오른쪽에 카테고리 전체 보기 --- */
.article-page .title-footer { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.article-page .title-footer .jd-cat-all {
  flex: 0 0 auto; font-size: 13px; font-weight: 600;
  color: var(--jd-accent) !important; text-decoration: none !important;
}
.article-page .title-footer .jd-cat-all:hover { text-decoration: underline !important; }

/* --- ③ 관련글: 대표이미지 없는 글의 빈 썸네일 박스 제거 --- */
.article-related .thumnail[style*="url('')"] { display: none !important; }

/* ===================================================================
   v6 (2026-10-21) — B안: Pro 페이지 + Liquid Glass
   ① 전역: 캔버스 #000, 유리 알약 메뉴바(.jd-gnav), 옛 header 숨김
   ② 홈(body#tt-body-index): 히어로 · 새 글 타일 · 유리 주제 카드 · 최근 글 그리드
   글 페이지 본문 흰 카드는 그대로 둔다.
   =================================================================== */
:root {
  --jd-canvas: #000000;
  --jd-glass: rgba(255,255,255,.06);
  --jd-glass-line: rgba(255,255,255,.12);
  --jd-glass-hi: inset 0 1px 0 rgba(255,255,255,.16);
  --jd-link-dark: #2997FF;
  --jd-ease: cubic-bezier(.25,.1,.25,1);
  --jd-ease-out: cubic-bezier(.22,1,.36,1);
}
body[id] { background: #000 !important; }

/* --- ① 유리 알약 메뉴바 --- */
header.header { display: none !important; }
.jd-gnav {
  position: sticky; top: 14px; z-index: 90;
  display: flex; align-items: center; gap: 6px;
  width: fit-content; max-width: calc(100% - 32px);
  margin: 14px auto 0; padding: 4px 6px 4px 22px; box-sizing: border-box;
  border-radius: 980px;
  background: rgba(28,28,30,.55);
  -webkit-backdrop-filter: blur(24px) saturate(170%); backdrop-filter: blur(24px) saturate(170%);
  border: 1px solid var(--jd-glass-line);
  box-shadow: var(--jd-glass-hi), 0 10px 30px -12px rgba(0,0,0,.7);
  font-family: var(--jd-font);
}
.jd-gnav-logo {
  margin-right: 12px; font-size: 16px; font-weight: 700; letter-spacing: -.02em;
  color: #F5F5F7 !important; text-decoration: none !important; white-space: nowrap;
}
.jd-gnav-links ul { display: flex; gap: 2px; margin: 0; padding: 0; list-style: none; }
.jd-gnav-links li { margin: 0; padding: 0; }
.jd-gnav-links a {
  display: inline-flex; align-items: center; min-height: 44px; padding: 0 12px;
  font-size: 14px; color: rgba(245,245,247,.82) !important; text-decoration: none !important;
  border-radius: 980px; transition: color .2s, background .2s; white-space: nowrap;
}
.jd-gnav-links a:hover { color: #fff !important; background: rgba(255,255,255,.08); }
.jd-gnav-search { position: relative; margin-left: 6px; }
.jd-gnav-search input {
  width: 132px; height: 36px; box-sizing: border-box; padding: 0 14px 0 34px;
  border-radius: 980px; border: 1px solid transparent;
  background: rgba(255,255,255,.08); color: #F5F5F7; font: 14px var(--jd-font);
  outline: none; transition: width .35s var(--jd-ease-out), background .2s, border-color .2s;
  -webkit-appearance: none; appearance: none;
}
.jd-gnav-search input::placeholder { color: #8E8E93; }
.jd-gnav-search input:focus { width: 200px; background: rgba(255,255,255,.12); border-color: rgba(41,151,255,.6); }
.jd-gnav-search svg { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); pointer-events: none; }
.jd-gnav .button-menu.jd-gnav-menu {
  position: static !important; display: inline-flex !important; align-items: center; justify-content: center;
  width: 44px; height: 44px; margin: 0; padding: 0; border: 0; border-radius: 50%;
  background: transparent; cursor: pointer; transition: background .2s;
}
.jd-gnav .button-menu.jd-gnav-menu:hover { background: rgba(255,255,255,.08); }
.wrap-drawer .area-aside { z-index: 200 !important; }
body.bg-dimmed .jd-gnav { z-index: 10; }
@media (max-width: 760px) {
  .jd-gnav { padding-left: 16px; gap: 0; }
  .jd-gnav-logo { margin-right: 4px; font-size: 15px; }
  .jd-gnav-links a { padding: 0 9px; font-size: 13px; }
  .jd-gnav-search { display: none; }
}

/* --- ② 홈 --- */
.jd-hero, .jd-latest-head { display: none; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .main { max-width: 1240px !important; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .area-main { position: relative; max-width: 1200px !important; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .area-common {
  position: relative;
  display: grid !important; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 20px;
  font-family: var(--jd-font);
}
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .area-common > * { grid-column: 1 / -1; order: 5; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .area-common > article.article-type-common { grid-column: auto; }
body#tt-body-index .area-common > .title-search { display: none !important; }
/* 유리가 비칠 은은한 색 번짐 (장식) */
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .area-common::before {
  content: ""; position: absolute; z-index: 0; inset: 520px -12% 0 -12%; pointer-events: none;
  background:
    radial-gradient(420px 420px at 6% 22%, rgba(41,151,255,.22), transparent 70%),
    radial-gradient(380px 380px at 96% 46%, rgba(191,90,242,.18), transparent 70%),
    radial-gradient(360px 360px at 40% 82%, rgba(48,209,88,.12), transparent 70%);
}
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .area-common > * { position: relative; z-index: 1; }

/* 히어로 */
body#tt-body-index .jd-hero { display: block; order: 1; text-align: center; padding: 104px 0 96px; }
.jd-hero-eyebrow { margin: 0 0 14px; font-size: 21px; font-weight: 600; color: #A1A1A6; }
.jd-hero-title {
  margin: 0; font-size: clamp(42px, 7vw, 92px) !important; line-height: 1.05 !important; font-weight: 700;
  letter-spacing: -.035em; word-break: keep-all;
  background: linear-gradient(180deg, #FFFFFF 0%, #C7C7CC 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.jd-hero-sub {
  margin: 26px auto 0; max-width: 640px; font-size: clamp(18px, 2vw, 23px); line-height: 1.42;
  color: #A1A1A6; word-break: keep-all;
}
.jd-hero-cta { margin-top: 38px; display: flex; gap: 24px; justify-content: center; align-items: center; flex-wrap: wrap; }
.jd-pill {
  display: inline-flex; align-items: center; min-height: 44px; padding: 0 22px; border-radius: 980px;
  background: var(--jd-accent); color: #fff !important; font-size: 17px; text-decoration: none !important;
  transition: background .2s;
}
.jd-pill:hover { background: var(--jd-accent-hi); }
.jd-more { font-size: 17px; color: var(--jd-link-dark) !important; text-decoration: none !important; }
.jd-more:hover { text-decoration: underline !important; }
.jd-more:after { content: " \203A"; }

/* 주제 카드 → 유리 벤토 */
body#tt-body-index .jd-topics { order: 3; margin: 108px 0 92px !important; }
body#tt-body-index .jd-topics-head { border: 0 !important; padding: 0 !important; margin: 0 0 36px !important; align-items: flex-end; flex-wrap: wrap; gap: 8px 16px; }
body#tt-body-index .jd-topics-title { font-size: clamp(30px, 3.4vw, 48px) !important; font-weight: 700 !important; letter-spacing: -.025em !important; line-height: 1.1; color: #F5F5F7 !important; }
