/* 최근 글 머리 */
body#tt-body-index .jd-latest-head { display: flex; order: 4; align-items: baseline; justify-content: space-between; flex-wrap: wrap; gap: 8px 16px; margin: 0 0 16px; }
.jd-latest-head h2 { margin: 0; font-size: clamp(30px, 3.4vw, 48px); font-weight: 700; letter-spacing: -.025em; line-height: 1.1; color: #F5F5F7; }

/* 글 카드 (공통) */
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common {
  display: flex !important; flex-direction: column !important; align-items: stretch !important; gap: 0 !important;
  padding: 0 !important; overflow: hidden; border-radius: 24px !important;
  background: var(--jd-glass) !important; border: 1px solid var(--jd-glass-line) !important;
  -webkit-backdrop-filter: blur(28px) saturate(160%); backdrop-filter: blur(28px) saturate(160%);
  box-shadow: var(--jd-glass-hi) !important;
  transition: transform .6s var(--jd-ease), border-color .6s, background .6s !important;
}
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common:hover { transform: scale(1.012) !important; border-color: rgba(255,255,255,.22) !important; background: rgba(255,255,255,.08) !important; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common > .link-article { display: block; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .thumbnail {
  display: flex !important; align-items: flex-end; width: 100% !important; min-width: 0 !important; height: auto !important;
  aspect-ratio: 16 / 9; margin: 0 !important; padding: 26px 28px; box-sizing: border-box;
  border-radius: 0 !important; background: var(--jd-tint, rgba(255,255,255,.06)) !important;
  border-bottom: 1px solid rgba(255,255,255,.08);
}
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .thumbnail .img-thumbnail { display: none !important; }
.jd-tile { font-size: 28px; line-height: 1.14; font-weight: 700; letter-spacing: -.025em; color: #F5F5F7; word-break: keep-all; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .article-content { display: flex; flex-direction: column; flex: 1; padding: 22px 28px 26px !important; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .article-content > .link-article { order: 2; flex: 1; }
.jd-eyebrow { display: none; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .jd-eyebrow { display: block; order: 1; margin: 0 0 8px; font-size: 12px; font-weight: 600; letter-spacing: .02em; color: var(--jd-acc, #A1A1A6); }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .title { font-size: 19px !important; line-height: 1.38 !important; font-weight: 600 !important; letter-spacing: -.015em !important; color: #F5F5F7 !important; margin: 0 0 10px !important; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .title img { display: none !important; }
.jd-sr { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .summary { display: none !important; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .box-meta { order: 3; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .box-meta .link-category,
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .box-meta .reply { display: none !important; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .date { padding: 0 !important; font-size: 14px !important; color: #86868B !important; }
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common .date:before { display: none !important; }
.jd-read { display: none; }

/* 새 글 타일 (홈 첫 글) — 시안 B: 왼쪽 글, 오른쪽 그 글의 출력·코드 창 */
body#tt-body-index .area-common > article.article-type-common.jd-featured {
  order: 2; grid-column: 1 / -1; flex-direction: row !important; flex-wrap: wrap; align-items: stretch !important; border-radius: 32px !important;
}
body#tt-body-index .area-common > article.article-type-common.jd-featured > .article-content { order: 1; flex: 1 1 440px; min-width: 0; justify-content: center; padding: 72px 64px !important; }
body#tt-body-index .area-common > article.article-type-common.jd-featured > .link-article { order: 2; flex: 1 1 440px; min-width: 0; display: flex !important; }
body#tt-body-index .area-common > article.article-type-common.jd-featured .thumbnail {
  flex: 1; height: auto !important; min-height: 340px; aspect-ratio: auto; align-items: center; justify-content: center;
  padding: 56px; background: transparent !important; border: 0 !important;
}
body#tt-body-index .area-common > article.article-type-common.jd-featured .jd-tile { font-size: clamp(40px, 4.4vw, 64px); line-height: 1.06; color: rgba(245,245,247,.9); }
body#tt-body-index .area-common > article.article-type-common.jd-featured .article-content > .link-article { flex: 0 0 auto; }
body#tt-body-index .area-common > article.article-type-common.jd-featured .jd-eyebrow { font-size: 17px; letter-spacing: 0; margin-bottom: 18px; }
body#tt-body-index.jd-p1 .area-common > article.article-type-common.jd-featured .jd-eyebrow { color: #FF9F0A; }
body#tt-body-index .area-common > article.article-type-common.jd-featured .title { font-size: clamp(34px, 3.6vw, 52px) !important; line-height: 1.08 !important; font-weight: 700 !important; letter-spacing: -.025em !important; margin: 0 0 18px !important; display: block !important; -webkit-line-clamp: unset !important; overflow: visible !important; max-height: none !important; height: auto !important; word-break: keep-all; }
body#tt-body-index .area-common > article.article-type-common.jd-featured .title .jd-m { position: static !important; display: block; width: auto; height: auto; overflow: visible; clip: auto; white-space: normal; }
body#tt-body-index .area-common > article.article-type-common.jd-featured .title .jd-h { display: block; margin-top: 14px; font-size: clamp(20px, 1.8vw, 24px); line-height: 1.3; font-weight: 600; letter-spacing: -.015em; color: #A1A1A6; }
body#tt-body-index .area-common > article.article-type-common.jd-featured .summary { display: -webkit-box !important; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; height: auto !important; max-height: none !important; font-size: 17px !important; line-height: 1.6 !important; color: #D2D2D7 !important; margin: 0 0 18px !important; }
body#tt-body-index .area-common > article.article-type-common.jd-featured .jd-read { display: inline; margin-right: 14px; font-size: 17px; color: var(--jd-link-dark); }
body#tt-body-index .area-common > article.article-type-common.jd-featured .jd-read:after { content: " \203A"; }
body#tt-body-index .area-common > article.article-type-common.jd-featured .box-meta { display: flex; align-items: baseline; }
.jd-win { display: block; width: 100%; max-width: 500px; border-radius: 18px; overflow: hidden; text-align: left; background: rgba(0,0,0,.55); border: 1px solid rgba(255,255,255,.1); box-shadow: 0 30px 60px -24px rgba(0,0,0,.8); }
.jd-win-bar { display: flex; align-items: center; gap: 8px; padding: 13px 16px; border-bottom: 1px solid rgba(255,255,255,.08); }
.jd-win-bar i { flex: none; width: 12px; height: 12px; border-radius: 50%; background: #FF5F57; }
.jd-win-bar i:nth-child(2) { background: #FEBC2E; }
.jd-win-bar i:nth-child(3) { background: #28C840; }
.jd-win-name { min-width: 0; margin-left: 10px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font: 12px "SF Mono", ui-monospace, Menlo, Consolas, monospace; color: #86868B; }
.jd-win-body {
  display: block; max-height: 236px; overflow: hidden; padding: 20px 22px 24px; white-space: pre; tab-size: 4;
  font: 13px/1.75 "SF Mono", ui-monospace, Menlo, Consolas, monospace; color: #F5F5F7;
  -webkit-mask-image: linear-gradient(180deg, #000 72%, transparent); mask-image: linear-gradient(180deg, #000 72%, transparent);
}
@media (max-width: 760px) {
  body#tt-body-index .area-common > article.article-type-common.jd-featured > .article-content { padding: 32px 26px !important; }
  body#tt-body-index .area-common > article.article-type-common.jd-featured .thumbnail { min-height: 0; padding: 0 20px 24px; }
  .jd-win-body { font-size: 12px; }
}

/* 페이지 번호 */
body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .area-paging { margin-top: 56px !important; }

/* 움직임 — 동작 줄이기 설정을 켠 사람에게는 끈다 */
@keyframes jdHeroIn { from { opacity: 0; transform: translateY(24px); filter: blur(8px); } to { opacity: 1; transform: none; filter: none; } }
@keyframes jdRise { from { opacity: 0; transform: translateY(48px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: no-preference) {
  body#tt-body-index .jd-hero > * { animation: jdHeroIn 1.1s var(--jd-ease-out) both; }
  body#tt-body-index .jd-hero > :nth-child(2) { animation-delay: .08s; }
  body#tt-body-index .jd-hero > :nth-child(3) { animation-delay: .16s; }
  body#tt-body-index .jd-hero > :nth-child(4) { animation-delay: .24s; }
  @supports (animation-timeline: view()) {
    body#tt-body-index .jd-topics-head, body#tt-body-index .jd-topic, body#tt-body-index .jd-latest-head,
    body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) article.article-type-common {
      animation: jdRise linear both; animation-timeline: view(); animation-range: entry 0% cover 22%;
    }
  }
}
@media (max-width: 760px) {
  body:is(#tt-body-index, #tt-body-category, #tt-body-search, #tt-body-archive) .area-common { grid-template-columns: 1fr; gap: 16px; }
  body#tt-body-index .jd-topics-grid { grid-template-columns: 1fr !important; }
  body#tt-body-index .jd-hero { padding: 64px 0 56px; }
  body#tt-body-index .jd-topics { margin: 72px 0 64px !important; }
  body#tt-body-index .jd-topic { min-height: 0; padding: 28px 24px 24px !important; }
  body#tt-body-index .jd-topic-name { font-size: 32px !important; }
}
html:has(body#tt-body-index) { scroll-behavior: smooth; }
#jd-topics, #jd-latest { scroll-margin-top: 96px; }

/* -------------------------------------------------------------------
   v6.1 (2026-10-21) — 나머지 페이지: 목록 머리 · 태그 · 글 머리 · 글 하단 · 드로어 · 푸터
   글 본문과 댓글 카드는 흰 종이 그대로 (tt- 위젯 아이콘 보호)
   ------------------------------------------------------------------- */
/* 목록 머리 (카테고리 · 검색 · 보관함) */
body:is(#tt-body-category, #tt-body-search, #tt-body-archive) .area-common::before { inset: 0 -12% 0 -12%; }
body:is(#tt-body-category, #tt-body-search, #tt-body-archive) .area-common > .title-search {
  display: flex !important; align-items: baseline; flex-wrap: wrap; gap: 6px 16px;
  margin: 72px 0 20px !important; padding: 0 !important; border: 0 !important; height: auto !important;
  font-family: var(--jd-font); line-height: 1.08 !important;
}
body:is(#tt-body-category, #tt-body-search, #tt-body-archive) .title-search b.archives {
  font-size: clamp(36px, 4.6vw, 64px) !important; font-weight: 700 !important; letter-spacing: -.03em !important; color: #F5F5F7 !important;
}
body:is(#tt-body-category, #tt-body-search, #tt-body-archive) .title-search span {
  font-size: clamp(18px, 1.8vw, 24px) !important; font-weight: 600 !important; color: #86868B !important;
}
body:is(#tt-body-category, #tt-body-search, #tt-body-archive) .title-search span:after { content: "\D3B8"; margin-left: 2px; }

/* 태그 페이지 */
#tt-body-tag .area-tag { max-width: 900px; margin: 0 auto; padding: 72px 0 40px; font-family: var(--jd-font); }
#tt-body-tag .area-tag .title-search {
  margin: 0 0 32px !important; padding: 0 !important; border: 0 !important;
  font-size: clamp(36px, 4.6vw, 64px) !important; font-weight: 700 !important; letter-spacing: -.03em !important; color: #F5F5F7 !important;
}
#tt-body-tag .area-tag .box-tag { display: flex; flex-wrap: wrap; gap: 10px; }
#tt-body-tag .area-tag .box-tag a {
  display: inline-flex; align-items: center; min-height: 44px; padding: 0 18px !important; margin: 0 !important; border-radius: 980px;
  background: var(--jd-glass); border: 1px solid var(--jd-glass-line); box-shadow: var(--jd-glass-hi);
  font-size: 15px !important; color: #F5F5F7 !important; text-decoration: none !important; transition: background .2s, border-color .2s;
}
#tt-body-tag .area-tag .box-tag a:hover { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.22); color: #fff !important; }
#tt-body-tag .area-tag .box-tag a:after { display: none !important; }

/* 글 머리 */
#tt-body-page .article-header.article-header-noimg { padding: 88px 0 48px !important; }
#tt-body-page .article-header .box-meta .category { font-size: 17px !important; font-weight: 600 !important; color: var(--jd-link-dark) !important; margin-bottom: 14px !important; }
#tt-body-page .article-header .title-article {
  font-size: clamp(34px, 4.2vw, 56px) !important; font-weight: 700 !important; letter-spacing: -.03em !important; line-height: 1.1 !important;
  background: linear-gradient(180deg, #FFFFFF 0%, #C7C7CC 100%); -webkit-background-clip: text; background-clip: text; color: transparent !important;
  word-break: keep-all; margin-bottom: 24px !important;
  display: block !important; -webkit-line-clamp: unset !important; overflow: visible !important; text-overflow: clip !important; padding-bottom: .06em;
}
#tt-body-page .article-header .box-info, #tt-body-page .article-header .box-info .writer, #tt-body-page .article-header .box-info .date { color: #86868B !important; font-size: 14px !important; }
#tt-body-page .article-header .box-info .btn_etc svg path { fill: #86868B !important; }

/* 글 하단: 다른 글 · 관련 글 → 유리 카드 (댓글 카드는 흰색 유지) */
body#tt-body-page .article-footer > .article-page,
body#tt-body-page .article-footer > .article-related {
  background: var(--jd-glass) !important; border: 1px solid var(--jd-glass-line) !important; border-radius: 28px !important;
  box-shadow: var(--jd-glass-hi) !important; padding: 30px 34px !important;
  -webkit-backdrop-filter: blur(28px) saturate(160%); backdrop-filter: blur(28px) saturate(160%);
}
body#tt-body-page .article-footer .title-footer {
  color: #F5F5F7 !important; font-size: 21px !important; font-weight: 700 !important; letter-spacing: -.02em !important;
  border-bottom: 1px solid rgba(255,255,255,.1) !important; padding-bottom: 14px !important; margin-bottom: 10px !important;
}
body#tt-body-page .article-page .title-footer .jd-cat-all { font-size: 15px; font-weight: 400; color: var(--jd-link-dark) !important; }
body#tt-body-page .article-page ul li { color: #F5F5F7 !important; font-size: 16px !important; padding: 10px 0; }
body#tt-body-page .article-page ul li span { color: #86868B !important; font-size: 13px !important; }
body#tt-body-page .article-page ul li a { display: flex; align-items: baseline; gap: 14px; }
body#tt-body-page .article-page ul li a, body#tt-body-page .article-page ul li strong { color: #F5F5F7 !important; }
body#tt-body-page .article-page ul li:nth-child(2) strong { color: #A1A1A6 !important; }
body#tt-body-page .article-page ul li a:hover strong { color: var(--jd-link-dark) !important; }
body#tt-body-page .article-related .list-related { gap: 14px !important; margin-top: 16px !important; }
body#tt-body-page .article-related .item-related { margin: 0 !important; }
body#tt-body-page .article-related .link-related {
  display: block; height: 100%; box-sizing: border-box; padding: 20px 22px; border-radius: 18px;
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.08); transition: background .2s, border-color .2s;
