body#tt-body-page .article-related .link-related:hover strong { color: var(--jd-link-dark) !important; }
body#tt-body-page .article-related .date { color: #86868B !important; font-size: 13px !important; }

/* 드로어 → 유리 */
.wrap-drawer .area-aside {
  background: rgba(22,22,24,.78) !important; border-left: 1px solid var(--jd-glass-line) !important;
  -webkit-backdrop-filter: blur(30px) saturate(170%); backdrop-filter: blur(30px) saturate(170%);
}
.area-aside .box-profile, .area-aside .box-category, .area-aside .box-recent, .area-aside .box-reply, .area-aside .box-notice,
.area-aside .box-tag, .area-aside .box-archive, .area-aside .box-calendar, .area-aside .box-visit, .area-aside .box-plugins {
  background: rgba(255,255,255,.05) !important; border: 1px solid rgba(255,255,255,.08) !important; border-radius: 20px !important;
}
.area-aside .box-tag a:last-child:after { background: transparent !important; }
.area-aside .searchInput { border-radius: 980px !important; background: rgba(255,255,255,.08) !important; color: #F5F5F7 !important; }

/* 푸터 */
footer#footer { background: transparent !important; border-top: 1px solid rgba(255,255,255,.1) !important; }
#footer .text-info, #footer address { color: #86868B !important; }
#footer .box-site:not(:has(li)) { display: none !important; }

@media (max-width: 760px) {
  body:is(#tt-body-category, #tt-body-search, #tt-body-archive) .area-common > .title-search { margin: 48px 0 12px !important; }
  #tt-body-tag .area-tag { padding: 48px 0 32px; }
  #tt-body-page .article-header.article-header-noimg { padding: 48px 0 28px !important; }
  body#tt-body-page .article-footer > .article-page,
  body#tt-body-page .article-footer > .article-related { padding: 22px 20px !important; border-radius: 22px !important; }
}

/* v6.5 (2026-10-21) — 목록 글 카드도 창: 그 글의 첫 출력 카드를 화면에 다가올 때 가져온다. 제목은 앞부분 + 회색 부제 두 줄 */
