/* v6.6 (2026-10-21) — 홈 최근 글 넘기기: 티스토리 페이지 번호 대신 아래 9칸만 바꾸는 번호 */
.jd-pager { display: none; }
body#tt-body-index .area-paging, body#tt-body-index .area-paging-more { display: none !important; }
body#tt-body-index .area-common > .jd-pager { display: flex; order: 6; grid-column: 1 / -1; justify-content: center; align-items: center; flex-wrap: wrap; gap: 6px; margin: 44px 0 0; }
.jd-pager a {
  display: inline-flex; align-items: center; justify-content: center; min-width: 44px; height: 44px; padding: 0 6px; box-sizing: border-box;
  border-radius: 980px; font: 500 15px var(--jd-font); color: #A1A1A6 !important; text-decoration: none !important; transition: background .2s, color .2s;
}
.jd-pager a:hover { background: rgba(255,255,255,.08); color: #F5F5F7 !important; }
.jd-pager a[aria-current="page"] { background: #F5F5F7; color: #000 !important; font-weight: 600; }
.jd-pager a.jd-off { opacity: .3; pointer-events: none; }
